205	
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
210	        Owner owner = this.clinicService.findOwnerById(ownerId);
211	        if (owner != null) {
212	            Pet pet = owner.getPet(petId);
213	            if (pet != null) {
214	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
215	            }
216	        }
217	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	    }
219	
220	    /**
221	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
222	     * The address is normalized in place (so a required-field check that follows rejects an
223	     * address blank after normalization), the required fields are checked, the telephone and
224	     * email are normalized in place, and the resulting telephone is rejected when it already
225	     * belongs to another owner. Each rule
226	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
227	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
228	     * to be mapped and saved.
229	     *
230	     * @param ownerFieldsDto the submitted owner fields, normalized in place
231	     */
232	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
233	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
234	        validateRequiredFields(ownerFieldsDto);
235	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
236	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
237	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
238	        rejectDuplicateHousehold(ownerFieldsDto);
239	        rejectCityAtCapacity(ownerFieldsDto.getCity());
240	    }
241	
242	    /**
243	     * The maximum number of owners a single city may hold. Once a city already contains this
244	     * many owners, no further owner may be created in it.
245	     */
246	    private static final long CITY_OWNER_CAPACITY = 50L;
247	
248	    /**
249	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
250	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
251	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
252	     * which the exception advice renders as a 409 Conflict response.
253	     *
254	     * @param city the city of the owner being created
255	     */
256	    private void rejectCityAtCapacity(String city) {
257	        long count = this.clinicService.findAllOwners().stream()
258	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
259	            .count();
260	        if (count >= CITY_OWNER_CAPACITY) {
261	            throw new CityCapacityExceededException(city);
262	        }
263	    }
264	
265	    /**
266	     * Builds the customer code assigned to a newly created owner. The code is formatted as
267	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
268	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
269	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
270	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
271	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
272	     *
273	     * @param city the owner's city
274	     * @param lastName the owner's last name
275	     * @return the formatted customer code
276	     */
277	    private String nextCustomerCode(String city, String lastName) {
278	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
279	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
280	        long sequence = this.clinicService.findAllOwners().stream()
281	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
282	            .count() + 1L;
283	        return String.format("%s-%s-%04d", city3, last3, sequence);
284	    }
285	
286	    /**
287	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
288	     * with the owner being created, compared case-insensitively. The count is taken before the
289	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
290	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
291	     *
292	     * @param firstName the first name of the owner being created
293	     * @param lastName the last name of the owner being created
294	     * @return the number of pre-existing owners sharing the same first and last name
295	     */
296	    private int countNamesakes(String firstName, String lastName) {
297	        return (int) this.clinicService.findAllOwners().stream()
298	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
299	                && lastName.equalsIgnoreCase(existing.getLastName()))
300	            .count();
301	    }
302	
303	    /**
304	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
305	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
306	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
307	     * the names of every offending field, which the exception advice renders as a 400 response
308	     * with an {@code errors} array.
309	     *
310	     * @param ownerFieldsDto the submitted owner fields
311	     */
312	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
313	        List<String> missing = new ArrayList<>();
314	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
315	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
316	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
317	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
318	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
319	        if (!missing.isEmpty()) {
320	            throw new RequiredFieldsMissingException(missing);
321	        }
322	    }
323	
324	    private void addIfBlank(List<String> missing, String fieldName, String value) {
325	        if (value == null || value.isBlank()) {
326	            missing.add(fieldName);
327	        }
328	    }
329	
330	    /**
331	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
332	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
333	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
334	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
335	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
336	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
337	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
338	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
339	     *
340	     * @param telephone the submitted telephone value
341	     * @return the normalized E.164 telephone
342	     */
343	    private String normalizeTelephone(String telephone) {
344	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
345	        String e164;
346	        if (cleaned.startsWith("+")) {
347	            e164 = "+" + cleaned.substring(1);
348	        } else {
349	            String national = cleaned;
350	            if (national.startsWith("0")) {
351	                national = national.substring(1);
352	            }
353	            e164 = "+61" + national;
354	        }
355	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
356	            throw new InvalidFieldsException(List.of("telephone"));
357	        }
358	        return e164;
359	    }
360	
361	    /**
362	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
363	     * and a domain containing at least one dot, none of the parts holding whitespace or a
364	     * second {@code @}.
365	     */
366	    private static final java.util.regex.Pattern EMAIL_PATTERN =
367	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
368	
369	    /**
370	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
371	     * accepted and returned unchanged. When present it must be a syntactically valid address;
372	     * the value is stored and returned lower-cased. When present but invalid an
373	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
374	     * response naming the {@code email} field.
375	     *
376	     * @param email the submitted email value, or {@code null} when omitted
377	     * @return the lower-cased email, or {@code null} when none was supplied
378	     */
379	    private String normalizeEmail(String email) {
380	        if (email == null) {
381	            return null;
382	        }
383	        String trimmed = email.trim();
384	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
385	            throw new InvalidFieldsException(List.of("email"));
386	        }
387	        return trimmed.toLowerCase(java.util.Locale.ROOT);
388	    }
389	
390	    /**
391	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
392	     * The telephone is stored in its normalized E.164 form, so a plain equality check
393	     * against every owner's telephone compares E.164 values. When a match is found a
394	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
395	     * 409 Conflict response.
396	     *
397	     * @param telephone the normalized telephone of the owner being created
398	     */
399	    private void rejectDuplicateTelephone(String telephone) {
400	        boolean taken = this.clinicService.findAllOwners().stream()
401	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
402	        if (taken) {
403	            throw new DuplicateTelephoneException(telephone);
404	        }
405	    }
406	
407	    /**
408	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
409	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
410	     * for how that identity is compared). A request may bypass this rule by setting
411	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
412	     * When a household mate is found and the request did not opt in a
413	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
414	     * Conflict response.
415	     *
416	     * @param ownerFieldsDto the submitted owner fields
417	     */
418	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
419	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
420	            return;
421	        }
422	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
423	        if (taken) {
424	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
425	        }
426	    }
427	
428	    /**
429	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
430	     * set to {@code true}. The identifier is derived deterministically from the owner's
431	     * household identity (its {@code lastName} and {@code address}, see
432	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
433	     * the same stable value. The new owner receives that value, and any existing household mates
434	     * that do not yet carry it are updated so the whole household shares one identifier. When the
435	     * request did not opt in the owner is left without a household identifier.
436	     *
437	     * @param owner the newly created owner, mutated in place with its household identifier
438	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
439	     */
440	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
441	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
442	            return;
443	        }
444	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
445	        owner.setHouseholdId(householdId);
446	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
447	            if (!householdId.equals(mate.getHouseholdId())) {
448	                mate.setHouseholdId(householdId);
449	                this.clinicService.saveOwner(mate);
450	            }
451	        }
452	    }
453	
454	    /**
455	     * Derives the stable {@code householdId} shared by every owner in the household identified by
456	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
457	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
458	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
459	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
460	     *
461	     * @param lastName the household's last name
462	     * @param address the household's address
463	     * @return the deterministic household identifier
464	     */
465	    private String householdIdFor(String lastName, String address) {
466	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
467	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
468	        try {
469	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
470	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
471	            StringBuilder sb = new StringBuilder();
472	            for (int i = 0; i < 8; i++) {
473	                sb.append(String.format("%02X", digest[i]));
474	            }
475	            return "HH-" + sb;
476	        }
477	        catch (java.security.NoSuchAlgorithmException e) {
478	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
479	        }
480	    }
481	
482	    /**
483	     * Finds an existing owner that shares a household with the given {@code lastName} and
484	     * {@code address}. When several owners match, the first one encountered is returned.
485	     *
486	     * @param lastName the last name to match on
487	     * @param address the address to match on
488	     * @return the first owner sharing the household, or empty when none exists
489	     */
490	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
491	        return findHouseholdMates(lastName, address).stream().findFirst();
492	    }
493	
494	    /**
495	     * Finds every existing owner that shares a household with the given {@code lastName} and
496	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
497	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
498	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
499	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
500	     * every rule that reasons about households.
501	     *
502	     * @param lastName the last name to match on
503	     * @param address the address to match on
504	     * @return the owners sharing the household, in encounter order (possibly empty)
505	     */
506	    private List<Owner> findHouseholdMates(String lastName, String address) {
507	        String normalizedLastName = collapseWhitespace(lastName);
508	        String normalizedAddress = normalizeAddress(address);
509	        return this.clinicService.findAllOwners().stream()
510	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
511	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
512	            .toList();
513	    }
514	
515	    /**
516	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
517	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
518	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
519	     *
520	     * @param value the value to collapse, or {@code null}
521	     * @return the whitespace-collapsed value, never {@code null}
522	     */
523	    private String collapseWhitespace(String value) {
524	        if (value == null) {
525	            return "";
526	        }
527	        return value.trim().replaceAll("\\s+", " ");
528	    }
529	
530	    /**
531	     * Common street-type abbreviations expanded during address normalization, keyed by their
532	     * upper-cased token.
533	     */
534	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
535	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
536	
537	    /**
538	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
539	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
540	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
541	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
542	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
543	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
544	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
545	     * everywhere an address is stored or compared.
546	     *
547	     * @param address the submitted address value, or {@code null}
548	     * @return the normalized address, never {@code null}
549	     */
550	    private String normalizeAddress(String address) {
551	        if (address == null) {
552	            return "";
553	        }
554	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
555	        if (collapsed.isEmpty()) {
556	            return "";
557	        }
558	        String[] tokens = collapsed.split(" ");
559	        StringBuilder sb = new StringBuilder(collapsed.length());
560	        for (int i = 0; i < tokens.length; i++) {
561	            if (i > 0) {
562	                sb.append(' ');
563	            }
564	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
565	        }
566	        return sb.toString();
567	    }
568	}
